/*
 * DAILY BANGLADESH HOLIDAY CHECK
 * Source: Nager.Date public-holiday API (country code BD).
 * Uses Asia/Dhaka local date to avoid UTC date-boundary errors.
 *
 * No holiday today = return zero items = Gmail node is not executed.
 * Multiple holidays today = one email item per holiday.
 */
const payload = $input.first()?.json ?? {};
const holidays = Array.isArray(payload) ? payload : (Array.isArray(payload.data) ? payload.data : []);

if (!holidays.length) {
  throw new Error("Holiday API returned no holiday records. Verify the API response and country/year.");
}

// Add government-announced or API-missing dates here using YYYY-MM-DD.
 // Example: { date: "2027-02-21", localName: "Shaheed Day", name: "International Mother Language Day", types: ["Public"] }
const customHolidays = [];

const mergedHolidays = [
  ...holidays,
  ...customHolidays.map(h => ({
    date: h.date,
    localName: h.localName || h.name,
    name: h.name || h.localName,
    types: h.types || ["Public"],
    countryCode: "BD"
  }))
];
const today = $now.setZone("Asia/Dhaka").toISODate();
const escapeHtml = value => String(value ?? "").replace(/[&<>"']/g, ch => ({
  "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;"
}[ch]));

const todays = mergedHolidays.filter(h => h.date === today);

if (!todays.length) {
  return [];
}

const readableDate = new Intl.DateTimeFormat("en-GB", {
  timeZone: "Asia/Dhaka",
  weekday: "long",
  day: "numeric",
  month: "long",
  year: "numeric"
}).format(new Date(`${today}T12:00:00+06:00`));

return todays.map(holiday => {
  const localName = holiday.localName || holiday.name || "Public Holiday";
  const englishName = holiday.name || localName;
  const types = Array.isArray(holiday.types) ? holiday.types.join(", ") : "";
  const subject = `Bangladesh Public Holiday Today: ${localName} | ${today}`;
  const html = `<!doctype html>
<html lang="en">
<head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<style>
body{margin:0;padding:24px;background:#f1f5f9;font-family:Arial,Helvetica,sans-serif;color:#172033}
.card{max-width:620px;margin:0 auto;background:#fff;border:1px solid #e2e8f0;border-radius:14px;overflow:hidden}
.top{padding:28px 30px;background:#123b2d;color:#fff}
.tag{font-size:11px;letter-spacing:1.7px;color:#b8e2cb;font-weight:bold}
h1{font-size:25px;line-height:1.3;margin:12px 0 5px}
.sub{font-size:13px;color:#d5eadc;margin:0}
.body{padding:28px 30px}
.notice{padding:18px;background:#f0fdf4;border:1px solid #bbf7d0;border-radius:10px}
.label{font-size:10px;letter-spacing:1px;color:#166534;font-weight:bold}
.name{font-size:22px;font-weight:bold;color:#14532d;margin:8px 0}
p{font-size:14px;line-height:1.7;color:#475569}
.meta{margin-top:18px;padding-top:14px;border-top:1px solid #e2e8f0;font-size:12px;color:#64748b}
.foot{padding:16px 30px;background:#f8fafc;border-top:1px solid #e2e8f0;font-size:10px;line-height:1.6;color:#94a3b8}
</style></head>
<body><div class="card">
<div class="top"><div class="tag">BANGLADESH · PUBLIC HOLIDAY NOTICE</div><h1>Today is a Public Holiday</h1><p class="sub">${escapeHtml(readableDate)}</p></div>
<div class="body">
<div class="notice"><div class="label">HOLIDAY</div><div class="name">${escapeHtml(localName)}</div><div style="font-size:13px;color:#166534">${escapeHtml(englishName)}</div></div>
<p>This is an automated notification that a public holiday is listed for Bangladesh today. Please plan meetings, office operations and business activities accordingly.</p>
<div class="meta"><b>Date:</b> ${escapeHtml(today)}<br><b>Country:</b> Bangladesh (BD)${types ? `<br><b>Holiday category:</b> ${escapeHtml(types)}` : ""}</div>
</div>
<div class="foot">Automated notification · Source: Nager.Date public-holiday API · Time zone: Asia/Dhaka<br>Please verify exceptional government-declared holidays and office-specific schedules through official Bangladesh government notices.</div>
</div></body></html>`;

  return {
    json: {
      date: today,
      localName,
      name: englishName,
      subject,
      html,
      countryCode: "BD",
      source: "Nager.Date"
    }
  };
});
